const fs=require("fs");
const dir="wiki/npcs";
const files=fs.readdirSync(dir).filter(f=>f.endsWith(".md"));
const out=[];
for(const f of files){
  const t=fs.readFileSync(dir+"/"+f,"utf8");
  const g=(re)=>{const m=t.match(re);return m?m[1].trim():null;};
  const lvl=g(/\*\*Combat Level\*\*\s*\|\s*([^\n|]+)/);
  const hp=g(/\*\*Hitpoints\*\*\s*\|\s*([^\n|]+)/);
  const sd=g(/Stab Defence\s*\|\s*(-?\d+)/);
  const sl=g(/Slash Defence\s*\|\s*(-?\d+)/);
  const cr=g(/Crush Defence\s*\|\s*(-?\d+)/);
  if(!lvl||!hp||sd===null)continue;
  const lv=parseInt(lvl), hpv=parseInt(hp);
  const maxdef=Math.max(parseInt(sd),parseInt(sl),parseInt(cr));
  if(lv>=8 && hpv>0 && maxdef<=0){
    out.push({name:f.replace(".md",""),lvl:lv,hp:hpv,def:maxdef});
  }
}
out.sort((a,b)=> (b.lvl/Math.max(1,a.hp))-(a.lvl/Math.max(1,b.hp)));
console.log(out.map(o=>`${o.name} lvl${o.lvl} hp${o.hp} def${o.def}`).join("\n"));
' 2>&1 | head -80

