function walk(d){let r=[];for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())r=r.concat(walk(p));else if(e.name.endsWith(".npc"))r.push(p);}return r;}
const files=walk("server/content/scripts");
const npcs=[];
for(const f of files){const t=fs.readFileSync(f,"utf8");let cur=null;
 for(const line of t.split(/\r?\n/)){const m=line.match(/^\[(\w+)\]/);if(m){cur={cfg:m[1],src:f};npcs.push(cur);continue;} if(!cur)continue; const kv=line.match(/^(\w+)=(.*)$/);if(kv)cur[kv[1]]=kv[2];}}
const out=[];
for(const n of npcs){const lv=parseInt(n.vislevel);if(isNaN(lv))continue;const hp=parseInt(n.hitpoints)||0;const def=parseInt(n.defence)||0;const str=parseInt(n.strength)||0;const atk=parseInt(n.attack)||0;
 if(lv>=7 && hp>0 && hp<=30 && def<=3 && str<=12){out.push({cfg:n.cfg,name:n.name,lv,hp,def,str,atk,rng:n.attackrange||"",op2:n.op2||""});}}
out.sort((a,b)=>b.lv-a.lv);
console.log(out.map(o=>`${o.name} [${o.cfg}] lvl${o.lv} hp${o.hp} def${o.def} str${o.str} atk${o.atk} rng${o.rng} ${o.op2}`).join("\n"));
' 2>&1 | head -100

